// gh-63 regression tests: the SOURCE_GITHUB_TOKEN push-credential machinery
// in the AI Teammate machine must never leak the workflows-capable PAT to
// non-github hosts (PR #68 review, BLOCKING thr…

blocks.text:
// gh-63 regression tests: the SOURCE_GITHUB_TOKEN push-credential machinery
// in the AI Teammate machine must never leak the workflows-capable PAT to
// non-github hosts (PR #68 review, BLOCKING thread) and must keep its
// at-push-time evidence honest. These tests pin the invariants of
//   agents/.github/workflows/factory-teammate.yml (the factory workflow)
//   agents/setup/install-source-git-credentials.sh (the shared installer)
// so a future edit cannot silently reintroduce the generic-helper leak or
// weaken the purge evidence.
import 'dart:io';

import 'package:test/test.dart';

// The credential machinery lives in the FACTORY (agents submodule,
// .github/workflows/factory-teammate.yml + setup/ scripts); the local
// ai-teammate.yml is a thin reusable-workflow stub over it. The pinned
// submodule makes the factory files part of this repo's merge tree.
const _workflowPath = 'agents/.github/workflows/factory-teammate.yml';
const _scriptPath = 'agents/setup/install-source-git-credentials.sh';

/// All YAML files that carry the credential machinery.
// Live credential surface = the FACTORY file (agents submodule, pinned).
// The legacy machine-kit template layer was retired (gh-146).
final List<String> _credentialYamlFiles = [_workflowPath];

String _read(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    fail('missing expected file: $path');
  }
  return file.readAsStringSync();
}

void main() {
  _hostScopingYaml();
  _hostScopingScript();
  _purgeEvidenceGate();
  _evidenceLogTagging();
  _dryRunFallbackReachable();
  _deduplicationIntoScript();
  _artifactSeesFinalPush();
  _identityRegex();
  _purgeTargetsRealCredentialSources();
  _submodulePurgeGateYaml();
  _dryRunAssertsHelperServedUsername();
  _persistStepReassertsPurge();
  _checkoutStopsPersistingAppToken();
  _extraheaderValueRedaction();
  _helperOperationGuard();
}

/// BLOCKING review thread 1 (YAML side): neither YAML file may install the
/// helper on the generic `credential.helper` key — git consults that for ANY
/// https host answering 401, handing the workflows-capable PAT to
/// attacker-controlled servers.
void _hostScopingYaml() {
  group(
      'SOURCE_GITHUB_TOKEN credential helper is host-scoped (gh-63, blocking)',
      () {
    for (final path in _credentialYamlFiles) {
      test(
          '$path never installs the helper on the generic credential.helper key',
          () {
        final genericHelperWrites = _read(path)
            .split('\n')
            .where((line) =>
                line.contains('credential.helper') &&
                line.contains('SOURCE_GITHUB_TOKEN'))
            .toList();
        expect(
          genericHelperWrites,
          isEmpty,
          reason: 'a SOURCE_GITHUB_TOKEN helper on the generic '
              'credential.helper key is consulted for ANY https host that '
              'answers 401 — register it on '
              'credential.https://github.com.helper instead',
        );
      });
    }
  });
}

/// BLOCKING review thread 1 (script side): URL-scoped registration behind
/// both list resets, plus the stdin host re-check as defense-in-depth.
void _hostScopingScript() {
  group('the shared script registers the helper host-scoped', () {
    final script = _read(_scriptPath);

    test('helper is registered on credential.https://github.com.helper', () {
      expect(
        script.contains(r'credential.https://github.com.helper "$helper"'),
        isTrue,
        reason: 'the helper must be registered on the URL-scoped key — '
            'a generic credential.helper is consulted for ANY https host '
            'whose server answers 401',
      );
      expect(
        script.contains('--add credential.https://github.com.helper'),
        isTrue,
        reason: 'the local push-path helper must be ADDED behind the reset',
      );
    });

    test('resets both inherited helper lists before installing its own', () {
      expect(
        script.contains(r"--replace-all credential.helper ''"),
        isTrue,
        reason: 'the generic reset wipes system/global generic helpers',
      );
      expect(
        script
            .contains(r"--replace-all credential.https://github.com.helper ''"),
        isTrue,
        reason: 'the scoped reset wipes system/global github.com helpers',
      );
    });

    test(
        'helper re-checks the host from stdin before answering (defense in depth)',
        () {
      expect(script, contains('host='));
      expect(
        script,
        contains(r'[ "$host" = "github.com" ] || return 0'),
        reason: 'the helper must answer nothing for non-github hosts '
            'even if it is ever registered generically',
      );
    });
  });
}

/// Review thread 2: the trace step must ASSERT the purge (`::error::` +
/// exit 1), not just print the value — a renamed checkout include file has to
/// fail the run instead of silently resurrecting the App token.
void _purgeEvidenceGate() {
  group('purge evidence is a gate, not a printout (gh-63, trace step)', () {
    for (final path in _credentialYamlFiles) {
      test('$path asserts the extraheader purge and fails the run otherwise',
          () {
        final source = _read(path);
        expect(
          source,
          contains('::error::App-token extraheader still present after purge'),
          reason: 'a silent print lets a renamed checkout include file '
              'resurrect the App token unnoticed',
        );
        expect(
          source.contains(
            r'git config --get-all http.https://github.com/.extraheader | grep -q .',
          ),
          isTrue,
          reason:
              'the trace step must turn the purge proof into a failing gate',
        );
      });
    }
  });
}

/// Review thread 3: trace dry-runs must tag their evidence-log lines
/// (CRED_HELPER_CONTEXT) so they cannot be mistaken for real pushes.
void _evidenceLogTagging() {
  group(
      'trace dry-runs are tagged so they cannot pollute push evidence (gh-63)',
      () {
    for (final path in _credentialYamlFiles) {
      test('$path dry-run sets CRED_HELPER_CONTEXT=trace-dry-run', () {
        expect(
          _read(path),
          contains('CRED_HELPER_CONTEXT=trace-dry-run'),
          reason: 'each untagged dry-run logs a line indistinguishable from a '
              'real push, inflating the at-push-time evidence',
        );
      });
    }

    test('the helper tags every log line with CRED_HELPER_CONTEXT', () {
      final script = _read(_scriptPath);
      expect(script, contains('CRED_HELPER_CONTEXT'));
      expect(
        script,
        contains('credential-helper.log'),
        reason: 'the helper log is the at-push-time proof of gh-63',
      );
    });
  });
}

/// Review thread 4: a pipeline's exit status is its LAST stage, and `sed`
/// exits 0 even on empty input — so the `|| echo` fallback after a sed stage
/// can never fire. Require the capture-then-branch form.
void _dryRunFallbackReachable() {
  group('trace dry-run failure fallback is reachable (gh-63)', () {
    for (final path in _credentialYamlFiles) {
      test('$path captures git credential fill output before branching', () {
        final source = _read(path);
        final pipelineForm = RegExp(
          r'git credential fill 2>&1( \\)?\s*\n?\s*\| sed',
        );
        expect(
          pipelineForm.hasMatch(source),
          isFalse,
          reason: 'the fallback must not depend on the exit status of a '
              'trailing sed stage',
        );
        expect(
          source.contains(
            RegExp(r'out="\$\(printf .+git credential fill 2>&1\)"'),
          ),
          isTrue,
          reason: 'capture the dry-run output, then redact-or-fallback',
        );
      });
    }
  });
}

/// Review thread 6: the ~40-line purge + helper block existed 6x across the
/// workflow and the template — the helper body must live in the shared script
/// only, and both files must invoke it.
void _deduplicationIntoScript() {
  group('credential machinery is deduplicated into the shared script (gh-63)',
      () {
    test('the helper one-liner exists exactly once — in the script…

messages.preview:
/// gh-261 regression guards: the Release CLI `version and tag` job pushes
/// the version-bump commit straight to the protected `main`, satisfying
/// branch protection by stamping success check-runs…

blocks.text:
/// gh-261 regression guards: the Release CLI `version and tag` job pushes
/// the version-bump commit straight to the protected `main`, satisfying
/// branch protection by stamping success check-runs for the required
/// contexts through the checks API (dm.ai release.yml pattern, ported 1:1).
///
/// When #187 split quality.yml into static/test/gate, branch protection
/// followed (the `quality` aggregate retired, `gate` + `static` became
/// required) — but the release workflow kept stamping the dead `quality`
/// name. Every release run since (34, 35, 36) died in "Push commit and
/// tag" with `GH006: Protected branch update failed ... 2 of 3 required
/// status checks are expected`, misread by the retry loop as "main moved".
///
/// These tests pin the stamped set to the contexts branch protection
/// requires and pin the retry-loop semantics that let the old failure
/// masquerade as a fast-forward race. If quality.yml renames a required
/// job again, the tests here and the workflow must move in lockstep.
library;

import 'dart:io';

import 'package:test/test.dart';

const _workflowPath = '.github/workflows/release-cli.yml';
const _qualityPath = '.github/workflows/quality.yml';

/// The contexts branch protection on `main` requires — the non-matrix
/// quality.yml surface (`gate` summarizes the `test (n)` shards; since
/// gh-315 `agents-gate` summarizes the sharded `agents-suite` matrix).
const _requiredContexts = {'static', 'gate', 'agents-gate'};

String _read(String path) {
  final file = File(path);
  if (!file.existsSync()) {
    fail('missing expected file: $path');
  }
  return file.readAsStringSync();
}

void main() {
  _stampSetGuards();
  _retryLoopGuards();
}

void _stampSetGuards() {
  final workflow = _read(_workflowPath);
  final quality = _read(_qualityPath);

  group('release-cli stamps the branch-protection-required contexts', () {
    test('stamped context set is exactly {static, gate, agents-gate}', () {
      final stampLoop = RegExp(r'for ctx in (.+?); do').firstMatch(workflow);
      expect(stampLoop, isNotNull,
          reason: '$_workflowPath must stamp the required check-runs via '
              'a `for ctx in <names>; do` loop (dm.ai release.yml pattern)');
      final stamped = stampLoop!.group(1)!.trim().split(RegExp(r'\s+')).toSet();
      expect(stamped, _requiredContexts,
          reason:
              'branch protection on main requires {${_requiredContexts.join(', ')}}; '
              'stamping {${stamped.join(', ')}} leaves the push rejected '
              'with "N of M required status checks are expected" (gh-261)');
    });

    test('the retired `quality` aggregate is no longer stamped', () {
      final stampLoop = RegExp(r'for ctx in (.+?); do').firstMatch(workflow)!;
      expect(stampLoop.group(1), isNot(contains('quality')),
          reason: 'no workflow has produced a `quality` check-run since '
              '#187 renamed the aggregate to `gate` — stamping it cannot '
              'satisfy any required context');
    });

    test('every stamped context is a real quality.yml job name', () {
      final jobs = _qualityJobNames(quality);
      for (final ctx in _requiredContexts) {
        expect(jobs, contains(ctx),
            reason: 'the release stamps `$ctx` as success — if quality.yml '
                'renamed that job, branch protection and the stamp set here '
                'must be updated in lockstep (gh-261: #187 renamed '
                'quality → gate and the releases silently broke)');
      }
    });
  });
}

void _retryLoopGuards() {
  final workflow = _read(_workflowPath);

  group('push retry loop cannot loop on protection declines', () {
    test('a rebase is followed by a re-stamp (new SHA has no check-runs)', () {
      final callCount = 'stamp_required_checks'.allMatches(workflow).length;
      expect(callCount, greaterThanOrEqualTo(3),
          reason: 'the stamp helper must be defined and invoked before the '
              'first push, and re-invoked inside the retry loop');
      final lines = workflow.split('\n');
      final rebaseLine = lines.indexWhere((l) => l.contains('git rebase '));
      expect(rebaseLine, greaterThanOrEqualTo(0),
          reason: 'the rebase-retry loop must exist (dm.ai parity)');
      final restampAfterRebase = lines
          .skip(rebaseLine + 1)
          .toList()
          .indexWhere((l) => l.trim() == 'stamp_required_checks');
      expect(restampAfterRebase, greaterThanOrEqualTo(0),
          reason: 'a rebase creates a NEW commit SHA whose required '
              'check-runs do not exist — without a re-stamp the retry '
              'attempt is rejected again and the loop burns all attempts');
    });

    test('a protection decline aborts instead of rebasing', () {
      final lines = workflow.split('\n');
      final declineGuard =
          lines.indexWhere((l) => l.contains('protected branch hook declined'));
      final rebaseLine = lines.indexWhere((l) => l.contains('git rebase '));
      expect(declineGuard, greaterThanOrEqualTo(0),
          reason: 'the push output must be inspected for the protection '
              'decline (GH006 "protected branch hook declined") — gh-261');
      expect(declineGuard, lessThan(rebaseLine),
          reason: 'the decline guard must run BEFORE the fetch/rebase '
              'fallback: rebasing cannot fix branch protection, and the '
              'old "main moved — rebasing" message lied about the cause '
              '(gh-261 runs 34/35/36)');
      expect(workflow, contains('::error::'),
          reason: 'a protection decline must surface a ::error:: naming '
              'the real cause instead of three identical retries');
    });
  });
}

/// Top-level job keys of quality.yml (2-space indent under `jobs:`).
Set<String> _qualityJobNames(String yml) {
  final lines = yml.split('\n');
  final jobsIndex = lines.indexWhere((l) => l.trim() == 'jobs:');
  expect(jobsIndex, greaterThanOrEqualTo(0),
      reason: 'quality.yml must declare jobs');
  final names = <String>{};
  for (final line in lines.skip(jobsIndex + 1)) {
    if (line.trim().isEmpty) {
      continue;
    }
    final job = RegExp(r'^  ([A-Za-z0-9_-]+):\s*$').firstMatch(line);
    if (job != null) {
      names.add(job.group(1)!);
      continue;
    }
    if (!line.startsWith('    ')) {
      break; // left the jobs: block (next 0-indent top-level key)
    }
  }
  return names;
}

